      "reason": "Prior villin/capsid work lacks AAV pH-resolved classification; stated gap makes result open."
    },
    {
      "criterion": "reshape",
      "value": 5,
      "ref": "plan:restructuring.condition_phase",
      "reason": "Pilot measures tau before ensemble; method replaces sequential dependency; prior lacks AAV system."
    },
    {
      "criterion": "baseline",
      "value": 5,
      "ref": "plan:phases",
      "reason": "Tuned baseline, same-GPU copies, occupancy check, and timed phases give measured gains."
    }
